package com.coraline.postgame;

import java.nio.file.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.tags.BlockTags;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.storage.LevelResource;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.level.*;
import net.minecraftforge.eventbus.api.*;
import net.minecraftforge.fml.common.Mod;

/** Conservative, bounded frontier infection. Only chunks observed as newly
 * generated in this epoch are eligible; historical player builds are never
 * guessed to be natural terrain. Original-state journals precede world edits. */
@Mod.EventBusSubscriber(modid="coraline")
public final class InfectionColonies {
    public static final List<String> VARIANTS=List.of("grass","soil","planks","leaves","stone","sand","gravel","base");
    private static final String VERSION="Version";
    private static final class Data extends SavedData {
        final UUID generation;CompoundTag raw;String problem="";
        Data(UUID id){generation=id;raw=new CompoundTag();raw.putInt(VERSION,1);raw.putUUID("Generation",id);for(String key:List.of("Chunks","Colonies","Originals"))raw.put(key,new CompoundTag());}
        Data(UUID id,CompoundTag n){generation=id;raw=n.copy();try{
            if(!n.contains(VERSION,Tag.TAG_INT)||n.getInt(VERSION)!=1||!n.hasUUID("Generation")||!id.equals(n.getUUID("Generation")))throw new IllegalArgumentException("Unknown infection schema");for(String key:List.of("Chunks","Colonies","Originals"))if(!n.contains(key,Tag.TAG_COMPOUND))throw new IllegalArgumentException("Incomplete infection journal");
            if(n.getCompound("Chunks").size()>4096||n.getCompound("Colonies").size()>8||n.getCompound("Originals").size()>4096)throw new IllegalArgumentException("Unbounded infection journal");
            for(String key:n.getCompound("Chunks").getAllKeys()){if(!Long.toString(Long.parseLong(key)).equals(key)||!n.getCompound("Chunks").contains(key,Tag.TAG_LONG_ARRAY)||n.getCompound("Chunks").getLongArray(key).length!=4)throw new IllegalArgumentException("Invalid protected columns");}
            var positions=new HashSet<Long>();var mobIds=new HashSet<UUID>();for(String key:n.getCompound("Colonies").getAllKeys()){if(!UUID.fromString(key).toString().equals(key)||!n.getCompound("Colonies").contains(key,Tag.TAG_COMPOUND))throw new IllegalArgumentException("Invalid colony ID");var row=n.getCompound("Colonies").getCompound(key);if(!row.contains("Heart",Tag.TAG_LONG)||!row.contains("Active",Tag.TAG_BYTE)||row.getByte("Active")<0||row.getByte("Active")>1||!row.contains("Frontier",Tag.TAG_LONG_ARRAY)||row.getLongArray("Frontier").length>256||!row.contains("Cells",Tag.TAG_LONG_ARRAY)||row.getLongArray("Cells").length>512||!row.contains("Next",Tag.TAG_LONG)||row.getLong("Next")<0||!row.contains("Cursor",Tag.TAG_INT)||row.getInt("Cursor")<0||row.getInt("Cursor")>512||!row.contains("Pending",Tag.TAG_INT)||row.getInt("Pending")<0||row.getInt("Pending")>512||!bounded(row.getLong("Heart")))throw new IllegalArgumentException("Invalid colony record");if(row.contains("Mobs")){if(!row.contains("Mobs",Tag.TAG_LIST))throw new IllegalArgumentException("Invalid converted actors");var mobs=row.getList("Mobs",Tag.TAG_INT_ARRAY);if(mobs.size()!=((ListTag)row.get("Mobs")).size()||mobs.size()>8)throw new IllegalArgumentException("Unbounded converted actors");for(var entry:mobs){if(!(entry instanceof IntArrayTag idArray)||idArray.getAsIntArray().length!=4||!mobIds.add(NbtUtils.loadUUID(entry)))throw new IllegalArgumentException("Ambiguous converted actor");}}for(long pos:row.getLongArray("Frontier"))if(!bounded(pos))throw new IllegalArgumentException("Invalid frontier");for(long pos:row.getLongArray("Cells"))if(!bounded(pos)||!positions.add(pos))throw new IllegalArgumentException("Overlapping infection memory");}
            if(positions.size()!=n.getCompound("Originals").size())throw new IllegalArgumentException("Orphaned infection snapshot");for(String key:n.getCompound("Originals").getAllKeys()){long pos=Long.parseLong(key);var cell=n.getCompound("Originals").getCompound(key);if(!Long.toString(pos).equals(key)||!positions.contains(pos)||!cell.contains(VERSION,Tag.TAG_INT)||cell.getInt(VERSION)!=1||!cell.hasUUID("Colony")||!n.getCompound("Colonies").contains(cell.getUUID("Colony").toString(),Tag.TAG_COMPOUND)||!cell.contains("Original",Tag.TAG_COMPOUND)||!cell.contains("Expected",Tag.TAG_COMPOUND)||!cell.contains("Changed",Tag.TAG_BYTE)||cell.getByte("Changed")<0||cell.getByte("Changed")>1||!cell.contains("Restored",Tag.TAG_BYTE)||cell.getByte("Restored")<0||cell.getByte("Restored")>1)throw new IllegalArgumentException("Invalid original-state snapshot");}
            for(String colony:n.getCompound("Colonies").getAllKeys()){
                var row=n.getCompound("Colonies").getCompound(colony);int pending=0;
                for(long position:row.getLongArray("Cells")){var cell=n.getCompound("Originals").getCompound(Long.toString(position));if(!cell.hasUUID("Colony")||!cell.getUUID("Colony").toString().equals(colony)||cell.contains("Position")&&(!cell.contains("Position",Tag.TAG_LONG)||cell.getLong("Position")!=position)||cell.contains("Dimension")&&(!cell.contains("Dimension",Tag.TAG_STRING)||!cell.getString("Dimension").equals("minecraft:overworld")))throw new IllegalArgumentException("Infection snapshot ownership changed");if(!cell.getBoolean("Restored"))pending++;}
                if(!row.getBoolean("Active")&&row.getInt("Pending")!=pending)throw new IllegalArgumentException("Infection restoration accounting changed");
            }
        }catch(IllegalArgumentException unknown){problem=unknown.getMessage();}}
        boolean commit(MinecraftServer server){if(!problem.isEmpty())return false;try{var p=file(server,generation);if(Files.isSymbolicLink(p)||Files.isSymbolicLink(p.getParent()))throw new java.io.IOException("Ambiguous infection storage");setDirty();server.overworld().getDataStorage().save();var n=com.coraline.rebirth.StoryRunStore.read(p);if(!n.contains("data",Tag.TAG_COMPOUND)||!n.getCompound("data").equals(raw))throw new java.io.IOException("Infection checkpoint mismatch");return true;}catch(java.io.IOException|RuntimeException failed){problem="Infection checkpoint failed";return false;}}
        @Override public CompoundTag save(CompoundTag n){return n.merge(raw.copy());}
    }
    private static String name(UUID id){return "coraline_infection_"+id;}
    private static Path file(MinecraftServer server,UUID id){return server.getWorldPath(LevelResource.ROOT).resolve("data/"+name(id)+".dat");}
    private static Data data(MinecraftServer server){return InfiniteWorldData.get(server).generation().map(id->data(server,id)).orElse(null);}
    private static Data data(MinecraftServer server,UUID id){return server.overworld().getDataStorage().computeIfAbsent(n->new Data(id,n),()->Files.notExists(file(server,id),LinkOption.NOFOLLOW_LINKS)?new Data(id):new Data(id,new CompoundTag()),name(id));}
    /** Retirement keeps the old snapshots independently of the active epoch.
     * It never loads terrain merely to finish cleanup and never deletes files. */
    private static final class Retirements extends SavedData {
        private static final String NAME="coraline_infection_retirements";
        private final CompoundTag raw;private String problem="";private int cursor;
        Retirements(){raw=new CompoundTag();raw.putInt("Version",1);raw.put("Epochs",new ListTag());}
        Retirements(CompoundTag n){raw=n.copy();try{if(!n.contains("Version",Tag.TAG_INT)||n.getInt("Version")!=1||!n.contains("Epochs",Tag.TAG_LIST))throw new IllegalArgumentException("Unknown restoration queue");var epochs=n.getList("Epochs",Tag.TAG_INT_ARRAY);if(epochs.size()!=((ListTag)n.get("Epochs")).size()||epochs.size()>32)throw new IllegalArgumentException("Unbounded restoration queue");var ids=new HashSet<UUID>();for(var row:epochs)if(!(row instanceof IntArrayTag array)||array.getAsIntArray().length!=4||!ids.add(NbtUtils.loadUUID(row)))throw new IllegalArgumentException("Invalid retired generation");}catch(IllegalArgumentException bad){problem=bad.getMessage();}}
        static Retirements get(MinecraftServer server){var path=server.getWorldPath(LevelResource.ROOT).resolve("data/"+NAME+".dat");return server.overworld().getDataStorage().computeIfAbsent(Retirements::new,()->Files.notExists(path,LinkOption.NOFOLLOW_LINKS)?new Retirements():new Retirements(new CompoundTag()),NAME);}
        List<UUID> ids(){return problem.isEmpty()?raw.getList("Epochs",Tag.TAG_INT_ARRAY).stream().map(NbtUtils::loadUUID).toList():List.of();}
        boolean add(MinecraftServer server,UUID id){if(!problem.isEmpty())return false;if(ids().contains(id))return true;var all=raw.getList("Epochs",Tag.TAG_INT_ARRAY);if(all.size()>=32)return false;all.add(NbtUtils.createUUID(id));return commit(server);}
        boolean commit(MinecraftServer server){try{if(!problem.isEmpty())return false;var path=server.getWorldPath(LevelResource.ROOT).resolve("data/"+NAME+".dat");if(Files.isSymbolicLink(path)||Files.isSymbolicLink(path.getParent()))throw new java.io.IOException("Ambiguous retirement storage");setDirty();server.overworld().getDataStorage().save();if(!com.coraline.rebirth.StoryRunStore.read(path).getCompound("data").equals(raw))throw new java.io.IOException("Retirement checkpoint mismatch");return true;}catch(java.io.IOException|RuntimeException bad){problem="Restoration retirement could not be saved safely";return false;}}
        @Override public CompoundTag save(CompoundTag n){return n.merge(raw.copy());}
    }
    static boolean canRetire(MinecraftServer server){var generation=InfiniteWorldData.get(server).generation().orElse(null);if(generation==null)return false;var queue=Retirements.get(server);var d=data(server,generation);return queue.problem.isEmpty()&&d.problem.isEmpty()&&(queue.ids().contains(generation)||queue.ids().size()<32);}
    /** The complete-ending transaction must receive true before it can retire
     * the active generation. Ordinary story replay never calls this adapter. */
    static boolean retire(MinecraftServer server,UUID generation){
        if(!server.isSameThread()||generation==null)return false;var queue=Retirements.get(server);if(!queue.problem.isEmpty()||!InfiniteWorldData.get(server).matchesGeneration(generation)&&!queue.ids().contains(generation))return false;
        var d=data(server,generation);if(!d.problem.isEmpty())return false;for(String key:d.raw.getCompound("Colonies").getAllKeys())stop(d,d.raw.getCompound("Colonies").getCompound(key));return d.commit(server)&&queue.add(server,generation);
    }
    private static void restoreRetired(MinecraftServer server){
        var queue=Retirements.get(server);var epochs=queue.ids();if(epochs.isEmpty())return;var id=epochs.get(Math.floorMod(queue.cursor++,epochs.size()));var d=data(server,id);if(!d.problem.isEmpty())return;
        for(String key:new HashSet<>(d.raw.getCompound("Colonies").getAllKeys())){var row=d.raw.getCompound("Colonies").getCompound(key);stop(d,row);restore(server.overworld(),d,UUID.fromString(key),row);}
        if(d.raw.getCompound("Colonies").isEmpty()&&d.raw.getCompound("Originals").isEmpty()&&d.commit(server)){var all=queue.raw.getList("Epochs",Tag.TAG_INT_ARRAY);all.removeIf(tag->NbtUtils.loadUUID(tag).equals(id));queue.commit(server);}
    }
    private static boolean bounded(long pos){var p=BlockPos.of(pos);return Math.abs((long)p.getX())<=29999920&&Math.abs((long)p.getZ())<=29999920&&p.getY()>=-64&&p.getY()<320;}
    private static boolean fresh(Data d,BlockPos at){var key=Long.toString(new ChunkPos(at).toLong());if(!d.raw.getCompound("Chunks").contains(key,Tag.TAG_LONG_ARRAY))return false;var bits=d.raw.getCompound("Chunks").getLongArray(key);int index=(at.getX()&15)+((at.getZ()&15)<<4);return (bits[index>>6]&(1L<<(index&63)))==0;}
    private static void modified(ServerLevel level,BlockPos at){var active=data(level.getServer());if(active!=null)modified(active,at);for(var id:Retirements.get(level.getServer()).ids())if(active==null||!id.equals(active.generation))modified(data(level.getServer(),id),at);}
    private static void modified(Data d,BlockPos at){if(!d.problem.isEmpty())return;String key=Long.toString(new ChunkPos(at).toLong());var chunks=d.raw.getCompound("Chunks");if(chunks.contains(key,Tag.TAG_LONG_ARRAY)){var bits=chunks.getLongArray(key);int index=(at.getX()&15)+((at.getZ()&15)<<4);bits[index>>6]|=1L<<(index&63);chunks.putLongArray(key,bits);}var originals=d.raw.getCompound("Originals");if(originals.contains(Long.toString(at.asLong()),Tag.TAG_COMPOUND))originals.getCompound(Long.toString(at.asLong())).putBoolean("Changed",true);d.setDirty();}
    @SubscribeEvent public static void chunk(ChunkEvent.Load event){if(!(event.getLevel() instanceof ServerLevel level)||level!=level.getServer().overworld()||!event.isNewChunk())return;var pos=event.getChunk().getPos();Runnable admit=()->{var d=data(level.getServer());if(d==null||!d.problem.isEmpty())return;var chunks=d.raw.getCompound("Chunks");String key=Long.toString(pos.toLong());if(chunks.size()<4096&&!chunks.contains(key)){chunks.putLongArray(key,new long[4]);d.setDirty();}};if(level.getServer().isSameThread())admit.run();else level.getServer().execute(admit);}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void broken(BlockEvent.BreakEvent event){if(!event.isCanceled()&&event.getLevel() instanceof ServerLevel level&&level==level.getServer().overworld())modified(level,event.getPos());}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void placed(BlockEvent.EntityPlaceEvent event){if(!event.isCanceled()&&event.getEntity() instanceof net.minecraft.world.entity.player.Player&&event.getLevel() instanceof ServerLevel level&&level==level.getServer().overworld())modified(level,event.getPos());}
    private static String kind(BlockState state){var id=net.minecraftforge.registries.ForgeRegistries.BLOCKS.getKey(state.getBlock());if(id==null||!id.getNamespace().equals("minecraft"))return null;if(state.hasBlockEntity()||state.isSignalSource()||state.hasAnalogOutputSignal())return null;if(state.is(Blocks.GRASS_BLOCK))return "grass";if(state.is(Blocks.DIRT)||state.is(Blocks.COARSE_DIRT)||state.is(Blocks.ROOTED_DIRT))return "soil";if(state.is(BlockTags.PLANKS))return "planks";if(state.is(BlockTags.LEAVES)&&(!state.hasProperty(LeavesBlock.PERSISTENT)||!state.getValue(LeavesBlock.PERSISTENT)))return "leaves";if(state.is(Blocks.STONE)||state.is(Blocks.ANDESITE)||state.is(Blocks.DIORITE)||state.is(Blocks.GRANITE)||state.is(Blocks.DEEPSLATE))return "stone";if(state.is(Blocks.SAND)||state.is(Blocks.RED_SAND))return "sand";if(state.is(Blocks.GRAVEL))return "gravel";if(state.is(Blocks.OBSIDIAN)||state.is(Blocks.TUFF)||state.is(Blocks.CALCITE))return "base";return null;}
    static void establish(ServerLevel level,BlockPos at,UUID raid){if(TrueHeartBattle.resetting(level.getServer()))return;if(level!=level.getServer().overworld())return;var view=BreachWorldData.get(level.getServer()).view();if(!view.active()||!view.blocker().isEmpty()||view.millionths()<1000000)return;var d=data(level.getServer());if(d==null||!d.problem.isEmpty()||d.raw.getCompound("Colonies").size()>=8||!level.hasChunkAt(at)||!fresh(d,at)||!level.isEmptyBlock(at)||!level.getFluidState(at).isEmpty()||level.getBlockEntity(at)!=null||kind(level.getBlockState(at.below()))==null)return;for(String key:d.raw.getCompound("Colonies").getAllKeys())if(BlockPos.of(d.raw.getCompound("Colonies").getCompound(key).getLong("Heart")).distSqr(at)<64*64)return;
        var id=UUID.randomUUID();var row=new CompoundTag();row.putUUID("Raid",raid);row.putLong("Heart",at.asLong());row.putBoolean("Active",true);row.putLongArray("Frontier",new long[]{at.below().asLong()});row.putLongArray("Cells",new long[0]);row.putLong("Next",level.getGameTime()+200);row.putInt("Cursor",0);row.putInt("Pending",0);d.raw.getCompound("Colonies").put(id.toString(),row);if(!d.commit(level.getServer()))return;level.setBlock(at,com.coraline.registry.ModBlocks.INFECTION_HEART.get().defaultBlockState(),3);if(!level.getBlockState(at).is(com.coraline.registry.ModBlocks.INFECTION_HEART.get()))stop(d,row);
    }
    private static void stop(Data d,CompoundTag row){if(!row.getBoolean("Active"))return;row.putBoolean("Active",false);row.putInt("Cursor",0);row.putInt("Pending",row.getLongArray("Cells").length);d.setDirty();}
    static void sourceRemoved(ServerLevel level,BlockPos at){var d=data(level.getServer());if(d==null||!d.problem.isEmpty())return;for(String key:d.raw.getCompound("Colonies").getAllKeys()){var row=d.raw.getCompound("Colonies").getCompound(key);if(row.getLong("Heart")==at.asLong())stop(d,row);}}
    private static BlockState decode(ServerLevel level,CompoundTag n){var id=ResourceLocation.tryParse(n.getString("Name"));if(id==null||!net.minecraftforge.registries.ForgeRegistries.BLOCKS.containsKey(id))return null;var block=net.minecraftforge.registries.ForgeRegistries.BLOCKS.getValue(id);if(n.contains("Properties")&&!n.contains("Properties",Tag.TAG_COMPOUND))return null;var props=n.getCompound("Properties");for(String key:props.getAllKeys()){var property=block.getStateDefinition().getProperty(key);if(property==null||!props.contains(key,Tag.TAG_STRING)||property.getValue(props.getString(key)).isEmpty())return null;}return NbtUtils.readBlockState(level.holderLookup(Registries.BLOCK),n);}
    private static void grow(ServerLevel level,Data d,UUID colony,CompoundTag row,int amount){var heart=BlockPos.of(row.getLong("Heart"));var queue=new ArrayDeque<Long>();for(long value:row.getLongArray("Frontier"))queue.add(value);var cells=new ArrayList<Long>();for(long value:row.getLongArray("Cells"))cells.add(value);var changes=new LinkedHashMap<BlockPos,BlockState>();int examined=0;
        while(!queue.isEmpty()&&examined++<16&&changes.size()<amount&&cells.size()<512&&d.raw.getCompound("Originals").size()<4096){long value=queue.removeFirst();var at=BlockPos.of(value);if(d.raw.getCompound("Originals").contains(Long.toString(value))||at.distSqr(heart)>12*12||!level.hasChunkAt(at)||!fresh(d,at)||level.getBlockEntity(at)!=null||!level.getFluidState(at).isEmpty())continue;var old=level.getBlockState(at);var type=kind(old);if(type==null)continue;var replacement=com.coraline.registry.ModBlocks.INFECTION_VARIANTS.get(type).get().defaultBlockState();var memory=new CompoundTag();memory.putInt(VERSION,1);memory.putString("Dimension","minecraft:overworld");memory.putLong("Position",value);memory.putUUID("Colony",colony);memory.put("Original",NbtUtils.writeBlockState(old));memory.put("Expected",NbtUtils.writeBlockState(replacement));memory.putBoolean("Changed",false);memory.putBoolean("Restored",false);d.raw.getCompound("Originals").put(Long.toString(value),memory);cells.add(value);changes.put(at,replacement);for(var dir:Direction.values()){long next=at.relative(dir).asLong();if(queue.size()<256&&!queue.contains(next)&&bounded(next))queue.addLast(next);}}
        row.putLongArray("Frontier",queue.stream().mapToLong(Long::longValue).toArray());row.putLongArray("Cells",cells.stream().mapToLong(Long::longValue).toArray());d.setDirty();if(changes.isEmpty()||!d.commit(level.getServer()))return;for(var entry:changes.entrySet()){var memory=d.raw.getCompound("Originals").getCompound(Long.toString(entry.getKey().asLong()));var original=decode(level,memory.getCompound("Original"));if(original!=null&&level.getBlockEntity(entry.getKey())==null&&level.getBlockState(entry.getKey()).equals(original))level.setBlock(entry.getKey(),entry.getValue(),3);else{memory.putBoolean("Changed",true);d.setDirty();}}
    }
    private static void restore(ServerLevel level,Data d,UUID colony,CompoundTag row){var cells=row.getLongArray("Cells");if(cells.length>0){int cursor=row.getInt("Cursor")%cells.length;for(int i=0;i<Math.min(8,cells.length);i++){long pos=cells[cursor];cursor=(cursor+1)%cells.length;var cell=d.raw.getCompound("Originals").getCompound(Long.toString(pos));var at=BlockPos.of(pos);if(cell.getBoolean("Restored")||!level.hasChunkAt(at))continue;var expected=decode(level,cell.getCompound("Expected"));var original=decode(level,cell.getCompound("Original"));if(expected==null||original==null)continue;if(!cell.getBoolean("Changed")&&level.getBlockEntity(at)==null&&level.getBlockState(at).equals(expected))level.setBlock(at,original,3);cell.putBoolean("Restored",true);row.putInt("Pending",Math.max(0,row.getInt("Pending")-1));d.setDirty();}row.putInt("Cursor",cursor);}
        if(row.getInt("Pending")!=0)return;var heart=BlockPos.of(row.getLong("Heart"));if(!level.hasChunkAt(heart))return;if(level.getBlockState(heart).is(com.coraline.registry.ModBlocks.INFECTION_HEART.get()))level.removeBlock(heart,false);for(long pos:cells)d.raw.getCompound("Originals").remove(Long.toString(pos));d.raw.getCompound("Colonies").remove(colony.toString());d.setDirty();
    }
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent event){var server=event.getServer();if(event.phase!=TickEvent.Phase.END||server.getTickCount()%20!=0)return;restoreRetired(server);var d=data(server);if(d==null||!d.problem.isEmpty())return;var level=server.overworld();var view=BreachWorldData.get(server).view();boolean contained=TrueHeartBattle.resetting(server)||!view.active()||!view.blocker().isEmpty()||view.millionths()<1000000;for(String key:new HashSet<>(d.raw.getCompound("Colonies").getAllKeys())){var row=d.raw.getCompound("Colonies").getCompound(key);var heart=BlockPos.of(row.getLong("Heart"));if(contained||level.hasChunkAt(heart)&&!level.getBlockState(heart).is(com.coraline.registry.ModBlocks.INFECTION_HEART.get()))stop(d,row);if(!row.getBoolean("Active")){restore(level,d,UUID.fromString(key),row);continue;}if(!level.hasChunkAt(heart)||level.getGameTime()<row.getLong("Next"))continue;row.putLong("Next",level.getGameTime()+(view.millionths()>=1500000?100:200));grow(level,d,UUID.fromString(key),row,view.millionths()>=1500000?4:2);}}
    @SubscribeEvent public static void command(AvatarInfectionPulse event){if(!event.avatar.authentic()||event.level!=event.level.getServer().overworld())return;var d=data(event.level.getServer());if(d==null||!d.problem.isEmpty())return;for(String key:d.raw.getCompound("Colonies").getAllKeys()){var row=d.raw.getCompound("Colonies").getCompound(key);if(row.getBoolean("Active"))row.putLong("Next",Math.min(row.getLong("Next"),event.level.getGameTime()+40));}d.setDirty();}
    record Source(UUID id,BlockPos heart){}
    static List<Source> sources(ServerLevel level){var d=data(level.getServer());if(d==null||!d.problem.isEmpty()||level!=level.getServer().overworld())return List.of();var out=new ArrayList<Source>();for(String key:d.raw.getCompound("Colonies").getAllKeys()){var row=d.raw.getCompound("Colonies").getCompound(key);var at=BlockPos.of(row.getLong("Heart"));if(row.getBoolean("Active")&&level.hasChunkAt(at)&&level.getBlockState(at).is(com.coraline.registry.ModBlocks.INFECTION_HEART.get()))out.add(new Source(UUID.fromString(key),at));}return out;}
    /** Unknown/unloaded is separate from a genuinely removed source. */
    static Optional<Boolean> sourceAlive(ServerLevel level,UUID colony){var d=data(level.getServer());if(d==null||!d.problem.isEmpty()||level!=level.getServer().overworld())return Optional.empty();if(!d.raw.getCompound("Colonies").contains(colony.toString(),Tag.TAG_COMPOUND))return Optional.of(false);var row=d.raw.getCompound("Colonies").getCompound(colony.toString());if(!row.getBoolean("Active"))return Optional.of(false);var at=BlockPos.of(row.getLong("Heart"));return level.hasChunkAt(at)?Optional.of(level.getBlockState(at).is(com.coraline.registry.ModBlocks.INFECTION_HEART.get())):Optional.empty();}
    static boolean ownsMob(ServerLevel level,UUID colony,UUID actor){var d=data(level.getServer());if(d==null||!d.problem.isEmpty()||level!=level.getServer().overworld()||BreachWorldData.get(level.getServer()).view().millionths()<1000000||!d.raw.getCompound("Colonies").contains(colony.toString(),Tag.TAG_COMPOUND))return false;var row=d.raw.getCompound("Colonies").getCompound(colony.toString());if(!row.getBoolean("Active"))return false;return row.getList("Mobs",Tag.TAG_INT_ARRAY).stream().anyMatch(n->NbtUtils.loadUUID(n).equals(actor));}
    static boolean admitMob(ServerLevel level,UUID colony,net.minecraft.world.entity.Mob actor){var d=data(level.getServer());if(d==null||!d.problem.isEmpty()||!fresh(d,actor.blockPosition())||!d.raw.getCompound("Colonies").contains(colony.toString(),Tag.TAG_COMPOUND))return false;var row=d.raw.getCompound("Colonies").getCompound(colony.toString());if(!row.getBoolean("Active"))return false;if(!row.contains("Mobs"))row.put("Mobs",new ListTag());var list=row.getList("Mobs",Tag.TAG_INT_ARRAY);if(list.stream().anyMatch(n->NbtUtils.loadUUID(n).equals(actor.getUUID())))return true;if(list.size()>=8)return false;for(String other:d.raw.getCompound("Colonies").getAllKeys())if(!other.equals(colony.toString())&&d.raw.getCompound("Colonies").getCompound(other).getList("Mobs",Tag.TAG_INT_ARRAY).stream().anyMatch(n->NbtUtils.loadUUID(n).equals(actor.getUUID())))return false;list.add(NbtUtils.createUUID(actor.getUUID()));return d.commit(level.getServer());}
    private InfectionColonies(){}
}
